  { name: 'Apollo Secondary Email Verification Source', aliases: ['Apollo Secondary Email Verification Source', 'Secondary Email Verification Source', 'secondary_email_verification_source'] },
  { name: 'Apollo Tertiary Email', aliases: ['Apollo Tertiary Email', 'Tertiary Email', 'tertiary_email'] },
  { name: 'Apollo Tertiary Email Source', aliases: ['Apollo Tertiary Email Source', 'Tertiary Email Source', 'tertiary_email_source'] },
  { name: 'Apollo Tertiary Email Status', aliases: ['Apollo Tertiary Email Status', 'Tertiary Email Status', 'tertiary_email_status'] },
  { name: 'Apollo Tertiary Email Verification Source', aliases: ['Apollo Tertiary Email Verification Source', 'Tertiary Email Verification Source', 'tertiary_email_verification_source'] },
  { name: 'Apollo Primary Intent Topic', aliases: ['Apollo Primary Intent Topic', 'Primary Intent Topic', 'primary_intent_topic'] },
  { name: 'Apollo Primary Intent Score', aliases: ['Apollo Primary Intent Score', 'Primary Intent Score', 'primary_intent_score'], transform: 'num' },
  { name: 'Apollo Secondary Intent Topic', aliases: ['Apollo Secondary Intent Topic', 'Secondary Intent Topic', 'secondary_intent_topic'] },
  { name: 'Apollo Secondary Intent Score', aliases: ['Apollo Secondary Intent Score', 'Secondary Intent Score', 'secondary_intent_score'], transform: 'num' },
  { name: 'Apollo Qualify Contact', aliases: ['Apollo Qualify Contact', 'Qualify Contact', 'qualify_contact'] },
];

let fieldByName = new Map();
let missingCustomFields = [];

if (apiKey) {
  const cfRes = await apiRequest.call(this, {
    method: 'GET',
    baseUrl: apiBaseUrl,
    path: `/locations/${locationId}/customFields?model=contact`,
    headers: authHeaders,
  });
  if (!cfRes.ok) throw new Error(`Failed to fetch contact custom fields: ${cfRes.status} ${JSON.stringify(cfRes.data)}`);
  const customFields = getArrayPayload(cfRes.data);
  fieldByName = new Map(customFields.map((f) => [String(f?.name || '').trim(), f]));
  missingCustomFields = customFieldSpecs.filter((f) => !fieldByName.get(f.name)?.id).map((f) => f.name);
  if (!dryRun && missingCustomFields.length) {
    throw new Error(`Missing required GHL custom fields: ${missingCustomFields.join(', ')}`);
  }
}

const results = [];
for (const rec of records) {
  const firstName = pick(rec, ['First Name', 'first_name', 'firstName']);
  const lastName = pick(rec, ['Last Name', 'last_name', 'lastName']);
  const email = pick(rec, ['Email', 'email']);
  const phone = pick(rec, ['Phone', 'phone', 'Mobile Phone', 'Corporate Phone', 'Work Direct Phone', 'Home Phone', 'Other Phone']);
  const companyName = pick(rec, ['Company Name', 'company_name', 'companyName']);
  const address1 = pick(rec, ['Address', 'address1', 'Company Address', 'company_address']);
  const website = pick(rec, ['Website', 'website']);
  const city = pick(rec, ['City', 'city', 'Company City', 'company_city']);
  const state = pick(rec, ['State', 'state', 'Company State', 'company_state']);
  const country = pick(rec, ['Country', 'country', 'Company Country', 'company_country']);
  const tags = parseTags(pick(rec, ['Tags', 'tags']), defaultTag);

  if (!email && !phone) {
    results.push({ status: 'skipped', reason: 'missing email and phone', firstName, lastName });
    continue;
  }

  const customValuesByName = {};
  for (const spec of customFieldSpecs) {
    const raw = pick(rec, spec.aliases);
    if (!raw) continue;
    let value = raw;
    if (spec.transform === 'num') {
      value = toNum(raw);
      if (value === null) continue;
    }
    if (spec.transform === 'date') {
      value = toDate(raw);
      if (!value) continue;
    }
    customValuesByName[spec.name] = value;
  }

  if (dryRun) {
    results.push({
      status: 'planned',
      email,
      phone,
      firstName,
      lastName,
      companyName,
      tags,
      standardFieldsPlanned: {
        firstName: !!firstName,
        lastName: !!lastName,
        email: !!email,
        phone: !!phone,
        companyName: !!companyName,
        address1: !!address1,
        website: !!website,
        city: !!city,
        state: !!state,
        country: !!country,
      },
      customFieldsPlanned: Object.keys(customValuesByName),
    });
    continue;
  }

  const upsertBody = {
    locationId,
    firstName: firstName || undefined,
    lastName: lastName || undefined,
    email: email || undefined,
    phone: phone || undefined,
    companyName: companyName || undefined,
    address1: address1 || undefined,
    website: website || undefined,
    city: city || undefined,
    state: state || undefined,
    country: country || undefined,
  };
  Object.keys(upsertBody).forEach((k) => upsertBody[k] === undefined && delete upsertBody[k]);

  const upsertRes = await apiRequest.call(this, {
    method: 'POST',
    baseUrl: apiBaseUrl,
    path: '/contacts/upsert',
    headers: authHeaders,
    body: upsertBody,
  });
  if (!upsertRes.ok) {
    results.push({ status: 'error', step: 'upsert', email, phone, details: upsertRes.data });
    continue;
  }

  const contactId = upsertRes.data?.contact?.id || upsertRes.data?.id || upsertRes.data?.contactId;
  if (!contactId) {
    results.push({ status: 'error', step: 'resolve_contact_id', email, phone, details: upsertRes.data });
    continue;
  }

  const updateEntries = [];
  for (const [name, value] of Object.entries(customValuesByName)) {
    const id = fieldByName.get(name)?.id;
    if (id) updateEntries.push({ id, value });
  }

  if (updateEntries.length) {
    const customFieldObject = Object.fromEntries(updateEntries.map((e) => [e.id, e.value]));
    const stampBodies = [
      { locationId, customField: customFieldObject },
      { customField: customFieldObject },
      { locationId, customFields: updateEntries.map((e) => ({ id: e.id, value: e.value })) },
      { customFields: updateEntries.map((e) => ({ id: e.id, value: e.value })) },
      { locationId, customFields: updateEntries.map((e) => ({ id: e.id, field_value: e.value })) },
      { customFields: updateEntries.map((e) => ({ id: e.id, field_value: e.value })) },
    ];

    let stampOk = false;
    let stampErr = null;
    for (const body of stampBodies) {
      const sr = await apiRequest.call(this, {
        method: 'PUT',
        baseUrl: apiBaseUrl,
        path: `/contacts/${contactId}`,
        headers: authHeaders,
        body,
      });
      if (sr.ok) { stampOk = true; break; }
      stampErr = sr;
    }

    if (!stampOk) {
      results.push({ status: 'error', step: 'custom_field_update', contactId, email, details: stampErr?.data || stampErr });
      continue;
    }
  }

  if (tags.length) {
    const tagsResult = await apiRequest.call(this, {
      method: 'POST',
      baseUrl: apiBaseUrl,
      path: `/contacts/${contactId}/tags`,
      headers: authHeaders,
      body: { tags },
    });
    if (!tagsResult.ok) {
      results.push({ status: 'error', step: 'tag_add', contactId, email, tags, details: tagsResult.data });
      continue;
    }
  }

  results.push({ status: 'imported', contactId, email, phone, tagsAdded: tags.length, customFieldsSet: updateEntries.length });
}

return [{
  json: {
    ok: true,
    dryRun,
    locationId,
    sourceRecords: records.length,
    imported: results.filter((r) => r.status === 'imported').length,
    planned: results.filter((r) => r.status === 'planned').length,
    skipped: results.filter((r) => r.status === 'skipped').length,
    errors: results.filter((r) => r.status === 'error').length,
    missingCustomFields,
    results: results.slice(0, 200),
    note: dryRun
      ? 'No API writes executed. Provide body.apiKey if you want custom-field existence checks during dry-run.'
      : 'Live run executed.',
  },
}];
